/* General Styles */
body {
  font-family: Arial, sans-serif;
  margin: 0;
  padding: 0;
  display: flex;
  background-color: #070724; /* Dark Blue Background */
}

.sidebar {
  width: 250px;
  background-color: #2daafe; /* Sidebar Background Color */
  color: white; /* Sidebar Text Color */
  padding-top: 20px;
  position: fixed; /* Fixed Sidebar */
  top: 0;
  left: 0;
  height: 100vh; /* Full-height */
}

.logo {
  width: 200px;
  height: auto;
  margin-bottom: 20px;
}

.sidebar ul {
  list-style-type: none;
  padding: 0;
}

.sidebar ul li {
  width: 100%;
}

.sidebar ul li span {
  display: block;
  padding: 10px 20px;
  text-decoration: none;
  color: white; /* Menu Item Text Color */
  font-size: 18px;
  background-color: #2daafe; /* Menu Item Background Color */
  border: 1px solid #1a8ec3; /* Slightly darker border */
}

.sidebar ul li span:hover {
  background-color: #1a8ec3; /* Darker blue on hover */
  font-weight: bold; /* Bold text on hover */
}

.main-content {
  margin-left: 250px; /* Offset for the fixed sidebar */
  padding: 20px;
  width: 100%;
}

.main-content h1 {
  font-size: 24px;
  color: white; /* Main Content Title Color */
}

.main-content ul {
  list-style-type: none;
  padding: 0;
}

.main-content ul li {
  font-size: 18px;
  color: white; /* Main Content List Item Color */
}

descriptor.controllerScript:
document.addEventListener('DOMContentLoaded', () => {
  // Function to load submenu content
  function loadSubMenuContent(menuId) {
    const content = {
      picture: `
        <h1>Picture Settings</h1>
        <ul>
          <li>Brightness</li>
          <li>Contrast</li>
          <li>Color Settings</li>
        </ul>
      `,
      osd: `
        <h1>OnScreen Display Settings</h1>
        <ul>
          <li>Display Mode</li>
          <li>Transparency</li>
        </ul>
      `,
      sound: `
        <h1>Sound Settings</h1>
        <ul>
          <li>Volume</li>
          <li>Balance</li>
          <li>Sound Mode</li>
        </ul>
      `,
      network: `
        <h1>Network Settings</h1>
        <ul>
          <li>Wi-Fi Settings</li>
          <li>Ethernet Settings</li>
        </ul>
      `,
      system: `
        <h1>System Settings</h1>
        <ul>
          <li>Time Settings</li>
          <li>Language</li>
          <li>Factory Reset</li>
        </ul>
      `,
      support: `
        <h1>Support</h1>
        <ul>
          <li>User Manual</li>
          <li>Firmware Updates</li>
        </ul>
      `
    };

    const mainContent = document.getElementById('main-content');
    mainContent.innerHTML = content[menuId];
  }

  // Add event listeners to menu items
  const menuItems = document.querySelectorAll('.menu-item');
  menuItems.forEach(item => {
    item.addEventListener('click', () => {
      const menuId = item.getAttribute('data-menu');
      loadSubMenuContent(menuId);
    });
  });

  // Load default 'Picture' submenu content
  loadSubMenuContent('picture');
});

